#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Mock rationale: Build the Docker image locally; no network calls are required.\nIMAGE_NAME="timezone-converter-test"\n\n# Build the image\ndocker build -t $IMAGE_NAME . > /dev/null\n\n# Define test parameters\nTIMESTAMP="2023-10-31 15:00"\nFROM_TZ="America/New_York"\nTO_TZ="Europe/London"\nEXPECTED="2023-10-31T20:00:00+00:00"\n\n# Run the container and capture output\nOUTPUT=$(docker run --rm $IMAGE_NAME "$TIMESTAMP" $FROM_TZ $TO_TZ)\n\n# Verify the output matches expectation\nif [[ "$OUTPUT" == "$EXPECTED" ]]; then\n  echo "✅ conversion test passed"\n  exit 0\nelse\n  echo "❌ conversion test failed"\n  echo "Expected: $EXPECTED"\n  echo "Got:      $OUTPUT"\n  exit 1\nfi
